fn dims() -> i32 {
    (480 << 16) | 270
}

fn frame(t: i32) {
    host::display::clear(0x0b0e12);
    let has: i32 = host::agent::viewer_has_identity();
    let subbed: i32 = host::agent::is_subscribed();
    let count: i32 = host::agent::subscriber_count();

    let mut subcol: i32 = 0x222a33;
    if subbed == 1 {
        subcol = 0x1a5c2a;
    }
    host::display::fill_rect(20, 60, 200, 150, subcol);
    if subbed == 1 {
        host::display::draw_string(58, 120, "LEAVE", 0x99ffbb, 3);
    } else {
        host::display::draw_string(66, 120, "JOIN", 0xffffff, 3);
    }

    host::display::fill_rect(260, 60, 200, 150, 0xdddddd);
    host::display::draw_string(288, 110, "READY", 0x000000, 3);
    host::display::draw_string(320, 145, "UP", 0x000000, 3);

    host::display::draw_string(20, 20, "SQUAD FEED", 0x8899aa, 2);
    host::display::draw_string(20, 235, "MEMBERS", 0x556677, 1);
    host::display::draw_number(90, 231, count, 0xffffff, 2);
    if has == 0 {
        host::display::fill_rect(0, 255, 480, 15, 0x6b3a16);
        host::display::draw_string(120, 259, "TAP ANYWHERE TO GET AN IDENTITY", 0xffcc88, 1);
    }

    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    if down == 1 && prev == 0 {
        if has == 0 {
            host::agent::request_identity();
        } else {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if py >= 60 && py < 210 {
                if px >= 20 && px < 220 {
                    if subbed == 1 {
                        host::agent::unsubscribe();
                    } else {
                        host::agent::subscribe();
                    }
                }
                if px >= 260 && px < 460 {
                    host::agent::broadcast_compose("Ready Up!", "Lobby is open - get in here.");
                }
            }
        }
    }
    host::display::present();
}
